import csv,json,re,math,unicodedata,collections
stop=set('who what which where when will be by the a an of in on at for to from with and or as its their after before first next new against into during about over under through than have has had this that these those is are was were do does did it his her whose named become receive score win lead make take record announce publicly confirm official officially match country city state team club player goal goal scorer opening final 2026 april may june july date resolved resolution'.split())
def norm(s):
 s=unicodedata.normalize('NFKD',s or '').encode('ascii','ignore').decode().lower()
 return re.findall(r\"[a-z0-9]+\",s)
arts=[]; seen=set()
for line in open('articles/2026/03/30/articles.jsonl',encoding='utf-8'):
 a=json.loads(line); title=a.get('title') or ''
 if not title or title in seen: continue
 seen.add(title)
 tt=set(norm(title)); ct=set(norm((a.get('content') or '')[:4000]))
 arts.append((title,tt,ct,a.get('source'),a.get('date_publish')))
df=collections.Counter()
for _,tt,ct,_,_ in arts:
 for t in tt|ct: df[t]+=1
N=len(arts)
rows=list(csv.DictReader(open('market.csv',newline='',encoding='utf-8')))
results=[]
for q in rows:
 text=(q['title']+' '+q['background'])
 qt={t for t in norm(text) if t not in stop and len(t)>2 and not t.isdigit()}
 # include outcome name tokens, but generic country outcomes can be noisy
 try: outcomes=json.loads(q['my_prediction'])
 except: outcomes={}
 ot={t for name in outcomes for t in norm(name) if t not in stop and len(t)>2}
 sig=qt|ot
 best=[]
 for title,tt,ct,source,date in arts:
  mt=sig&tt; mc=(sig&ct)-mt
  if not mt and len(sig&ct)<2: continue
  score=sum(math.log((N+1)/(df[t]+1))*3 for t in mt)+sum(math.log((N+1)/(df[t]+1)) for t in mc)
  # exact distinctive bigram overlap in question vs title
  qn=' '.join(norm(q['title'])); tn=' '.join(norm(title))
  for name in outcomes:
   nn=' '.join(norm(name))
   if len(nn)>=7 and ' ' in nn and nn in tn: score+=8
  if score>=10: best.append((score,title,source,date,sorted(mt)))
 best=sorted(best,reverse=True)[:2]
 if best: results.append((best[0][0],q['qid'],q['title'],best))
for mx,qid,qt,best in sorted(results,reverse=True)[:120]:
 print(f\"\\n{mx:.1f} QID {qid} {qt}\")
 for s,t,src,d,mt in best: print(f\"  {s:.1f} | {t} | {src} | {d} | titlematch={','.join(mt)}\")
PY"

